{
  "findings": [
    {
      "check_id": "CKV_GCP_83",
      "title": "Ensure PubSub Topics are encrypted with Customer Supplied Encryption Keys (CSEK)",
      "resource": "google_pubsub_topic.notification_queue",
      "severity": "MEDIUM",
      "explanation": "The PubSub topic is not encrypted with a Customer Supplied Encryption Key (CSEK), potentially allowing unauthorized access to the data it contains."
    }
  ],
  "patched_code": "resource \"google_pubsub_topic\" \"notification_queue\" {\n  name = \"insurance-claims-processing-platform-pubsub-notifications\"\n  labels = {\n    environment = \"production\"\n    component   = \"notifications\"\n  }\n  kms_key_name = \"projects/your-project/locations/your-location/keyRings/your-keyring/cryptoKeys/your-key\"\n}",
  "fix_summary": "Added kms_key_name attribute to the google_pubsub_topic resource to enable encryption with a Customer Supplied Encryption Key (CSEK)."
}
